const EU_LANGUAGES=[['中文','zh','中文'],['Deutsch','de','Deutsch'],['English','en','English'],['Tiếng Việt','vi','Tiếng Việt'],['한국어','ko','한국어'],['日本語','ja','日本語']];
function euLang(){const key=euSession.key||euInvitation()?.key;const d=empRead(EU_KEY,{})[key];return EU_LANGUAGES.find(x=>x[0]===d?.profile?.language)?.[1]||'de';}
function euTranslate(text,lang=euLang()){
 const map=EU_TRANSLATIONS[lang];if(!map||!text)return text;
 const trimmed=text.trim();if(map[trimmed])return text.replace(trimmed,map[trimmed]);
 const keys=Object.keys(map).filter(key=>key.length>1||key==='项'||key==='项'||key==='项').sort((a,b)=>b.length-a.length);
 const pattern=new RegExp(keys.map(key=>key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
 return text.replace(pattern,key=>map[key]).replace(/(^|[、：，\s])([名姓])(?=$|[、，\s])/g,(_,prefix,key)=>prefix+map[key]);
}
function euApplyLanguage(){const lang=euLang();document.documentElement.lang=lang==='zh'?'zh-CN':lang;
 const scope=document.querySelector('main.main');if(!scope)return;
 scope.lang=lang;scope.dataset.employeeLanguage=lang;
 const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest('[data-no-translate],script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>node.nodeValue=euTranslate(node.nodeValue,lang));
 scope.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr))el.setAttribute(attr,euTranslate(el.getAttribute(attr),lang));});
 const globalSelect=document.querySelector('#languageSelect');if(globalSelect)globalSelect.closest('.top-actions')?.querySelector('#languageSelect').style.setProperty('display','none');
}

